SELECT Имена_станций.NAME, Имена_ОЭС.nameoes, Имена_областей.NAME AS oblname, St_arh.numb1, St_arh.Year, St_arh.nust, St_arh.nr, IIf([E]>0,[E],0) AS W, St_arh.ewtp, St_arh.eotp, St_arh.eurt, St_arh.eust, IIf([Q]>0,[Q],0) AS Qotp, IIf([qotr]>0,[qotr],0) AS Q_otr, St_arh.turt, St_arh.tust, St_arh.B, IIf([gaz]>0,[gaz],0) AS GAZ_EST, IIf([gazpp]>0,[gazpp],0) AS poput_gaz, IIf([gaz_prir]>0,[gaz_prir],0) AS prirod_gaz, IIf([isk_gaz]>0,[isk_gaz],0) AS GAZ_ISK, IIf([domen_g]>0,[domen_g],0) AS domen_gaz, IIf([koks_g]>0,[koks_g],0) AS koks_gaz, IIf([prochgaz]>0,[prochgaz],0) AS proch_gaz, St_arh.MAZUT, Dop_arh.maztop, Dop_arh.disel, Dop_arh.gtt, Dop_arh.nft_proch, IIf([torf]>0,[torf],0) AS TORF_6tp, St_arh.SLAN, St_arh.PROCH, IIf([szh_gaz]>0,[szh_gaz],0) AS szhizh_gaz, IIf([tvproch]>0,[tvproch],0) AS proch_tverd, IIf([inoe]>0,[inoe],0) AS inoe_topl, IIf([ugol]>0,[ugol],0) AS UGOL_6tp, St_arh.don, St_arh.podm, St_arh.pech, Dop_arh.intin, Dop_arh.vork, St_arh.arkt, St_arh.kuzn, Dop_arh.kuzngd, Dop_arh.kuznt, Dop_arh.kuznss, Dop_arh.kuznun, St_arh.ural, Dop_arh.sver, Dop_arh.chel, Dop_arh.kizel, St_arh.bashk, St_arh.kazah, Dop_arh.ekib, Dop_arh.maikub, Dop_arh.karag, Dop_arh.karajyra, Dop_arh.teniz, St_arh.kan, Dop_arh.nazar, Dop_arh.ibor, Dop_arh.berez, Dop_arh.per, Dop_arh.irbei, Dop_arh.kansk, St_arh.tung, Dop_arh.jer, Dop_arh.karab, St_arh.irkut, Dop_arh.mug, Dop_arh.azey, Dop_arh.cher, St_arh.hak, St_arh.tuv, St_arh.bur, Dop_arh.gusin, Dop_arh.tugn, Dop_arh.okino, St_arh.chit, Dop_arh.har, Dop_arh.urt, Dop_arh.zab_kam, Dop_arh.tarbag, Dop_arh.tataur, St_arh.yakut, Dop_arh.neru, Dop_arh.zyryan, Dop_arh.pyak, St_arh.amur, Dop_arh.rai, Dop_arh.erk, Dop_arh.ogodj, Dop_arh.svo, St_arh.urg, St_arh.prim, Dop_arh.hankai, Dop_arh.razdol, Dop_arh.bikin, St_arh.mag, St_arh.sah, St_arh.ushum, St_arh.kamch, St_arh.chukot, Dop_arh.anad, Dop_arh.bering, IIf(IsNull([DON]),0,[DON])+IIf(IsNull([HAK]),0,[HAK])+IIf(IsNull([TUV]),0,[TUV])+IIf(IsNull([URG]),0,[URG])+IIf(IsNull([MAG]),0,[MAG])+IIf(IsNull([KAMCH]),0,[KAMCH])+IIf(IsNull([tugn]),0,[tugn])+IIf(IsNull([cher]),0,[cher])+IIf(IsNull([jer]),0,[jer])+IIf(IsNull([karab]),0,[karab])+IIf(IsNull([vork]),0,[vork])+IIf(IsNull([intin]),0,[intin])+IIf(IsNull([kizel]),0,[kizel])+IIf(IsNull([zab_kam]),0,[zab_kam])+IIf(IsNull([ogodj]),0,[ogodj])+IIf(IsNull([razdol]),0,[razdol])+IIf(IsNull([neru]),0,[neru])+IIf(IsNull([zyryan]),0,[zyryan])+IIf(IsNull([pyak]),0,[pyak])+IIf(IsNull([kuzngd]),0,[kuzngd])+IIf(IsNull([kuznt]),0,[kuznt])+IIf(IsNull([kuznss]),0,[kuznss])+IIf(IsNull([kuznun]),0,[kuznun])+IIf(IsNull([bering]),0,[bering])+IIf(IsNull([ekib]),0,[ekib])+IIf(IsNull([karag]),0,[karag])+IIf(IsNull([karajyra]),0,[karajyra]) AS Kamennie, IIf(IsNull([PODM]),0,[PODM])+IIf(IsNull([BASHK]),0,[BASHK])+IIf(IsNull([USHUM]),0,[USHUM])+IIf(IsNull([SAH]),0,[SAH])+IIf(IsNull([nazar]),0,[nazar])+IIf(IsNull([ibor]),0,[ibor])+IIf(IsNull([berez]),0,[berez])+IIf(IsNull([per]),0,[per])+IIf(IsNull([irbei]),0,[irbei])+IIf(IsNull([kansk]),0,[kansk])+IIf(IsNull([gusin]),0,[gusin])+IIf(IsNull([okino]),0,[okino])+IIf(IsNull([azey]),0,[azey])+IIf(IsNull([mug]),0,[mug])+IIf(IsNull([sver]),0,[sver])+IIf(IsNull([chel]),0,[chel])+IIf(IsNull([har]),0,[har])+IIf(IsNull([urt]),0,[urt])+IIf(IsNull([tataur]),0,[tataur])+IIf(IsNull([tarbag]),0,[tarbag])+IIf(IsNull([rai]),0,[rai])+IIf(IsNull([erk]),0,[erk])+IIf(IsNull([svo]),0,[svo])+IIf(IsNull([bikin]),0,[bikin])+IIf(IsNull([hankai]),0,[hankai])+IIf(IsNull([anad]),0,[anad])+IIf(IsNull([maikub]),0,[maikub])+IIf(IsNull([teniz]),0,[teniz]) AS Burie, St_arh.snk, St_arh.SNT, St_arh.NTsum, St_arh.nt, St_arh.obor, Типы_оборудования.gruppa_oborud, St_arh.ved, St_arh.obl, St_arh.dep, St_arh.oes, St_arh.er, St_arh.numb1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.BE AS BE, Имена_станций.GK AS GK, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"ГУБТ и ВЭР",IIf([obor]=24 Or [obor]=89,"ГПА",IIf([obor]=95,"котельн","ПСУ")))))) AS тип, IIf([be]<>9,имена_ГК!name1,имена_БЕ!name) AS nameGK, IIf([B]>0,[gaz_prir]/[B]*100,0) AS dolya_gaz_prir, IIf([B]>0,[gazpp]/[B]*100,0) AS dolya_gazpp, IIf([B]>0,[UGOL]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[MAZUT]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[TORF]/[B]*100,0) AS dolya_torf, IIf([B]>0,[SLAN]/[B]*100,0) AS dolya_slan, IIf([B]>0,[PROCH]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf([B]>0,IIf([dolya_gaz_prir]>=50,"gaz_prir",IIf([dolya_gazpp]>=50,"gazpp",IIf([dolya_domen_g]>=50,"domen_g",IIf([dolya_koks_g]>=50,"koks_g",IIf([dolya_prochgaz]>=50,"prochgaz",IIf([dolya_ugol]>=50,"ugol",IIf([dolya_mazut]>=50,"neftetopl","prochee"))))))),"net topliva") AS nov_Belyaev, Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций.BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM (имена_ГК INNER JOIN (имена_БЕ INNER JOIN (Имена_ОЭС INNER JOIN (Имена_областей INNER JOIN (([Станции(архив)] AS St_arh INNER JOIN Имена_станций ON St_arh.numb1120 = Имена_станций.NUMB) LEFT JOIN [Доп_угли(архив)] AS Dop_arh ON (St_arh.numb1120 = Dop_arh.NUMB1120) AND (St_arh.year = Dop_arh.YEAR)) ON Имена_областей.OBL = Имена_станций.OBL) ON Имена_ОЭС.oes = Имена_станций.OES) ON имена_БЕ.code = Имена_станций.BE) ON имена_ГК.code = Имена_станций.GK) LEFT JOIN Типы_оборудования ON St_arh.obor = Типы_оборудования.code
WHERE (((St_arh.Year)>2017))
ORDER BY St_arh.Year;
